def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluate the consistency of a scenario with the given statements,
    assuming that participants in liar_count always lie.
    Disregards any statement that contains a day of the week.
    """
    import re

    # Normalise days of the week to lowercase for comparison
    days_lc = {day.lower() for day in days_of_week}

    # Helper to check if a statement is a day-related statement
    def is_day_statement(stmt: str) -> bool:
        stmt_lc = stmt.lower()
        return any(day in stmt_lc for day in days_lc)

    # Regular expressions for statement parsing
    i_guilty_re = re.compile(r"^i am guilty$")
    i_not_guilty_re = re.compile(r"^i am not guilty$")
    name_guilty_re = re.compile(r"^(\w+) is guilty$")
    name_not_guilty_re = re.compile(r"^(\w+) is not guilty$")

    # Determine if the scenario person is the guilty one
    def is_guilty(person: str) -> bool:
        return person == scenario

    for speaker, stmts in statements.items():
        # Whether this speaker is assumed to be a liar
        liar = speaker in liar_count

        for stmt in stmts:
            # Skip day-related statements
            if is_day_statement(stmt):
                continue

            # Clean statement: strip whitespace, lowercase, remove trailing periods
            stmt_clean = stmt.strip().lower().rstrip('.')

            # Identify the statement type
            truth = None  # Whether the statement is true under the scenario

            if i_guilty_re.match(stmt_clean):
                truth = is_guilty(speaker)
            elif i_not_guilty_re.match(stmt_clean):
                truth = not is_guilty(speaker)
            else:
                m = name_guilty_re.match(stmt_clean)
                if m:
                    name = m.group(1).strip().capitalize()
                    truth = is_guilty(name)
                else:
                    m = name_not_guilty_re.match(stmt_clean)
                    if m:
                        name = m.group(1).strip().capitalize()
                        truth = not is_guilty(name)

            # If we couldn't parse the statement, ignore it
            if truth is None:
                continue

            # Check consistency with liar status
            if liar:
                if truth:
                    # Liar said a true statement
                    return False
            else:
                if not truth:
                    # Truthful speaker said a false statement
                    return False

    return True

